WHERE modules.status = 1
AND modules.module_type_id = #{filter.moduleTypeId}

  AND (
    modules.name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR module_types.name LIKE CONCAT('%', #{filter.searchText}, '%')
