mapper.select:
SELECT



ORDER BY


    ${filter.orderBy}


    modules.ordering ASC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM modules
WHERE status = 1 AND name = #{name}
AND module_type_id = #{moduleTypeId}
AND id != #{id}

mapper.update:
UPDATE modules
SET status = 0,
    modified = NOW(),
    modified_by = #{userId}
WHERE id = #{id}
  AND status = 1
